'use strict';

const QUOTE = 0x22; // "
const CR = 0x0d;
const LF = 0x0a;
const BOM = 0xfeff;

// Parser states.
const RECORD_START = 0; // at the start of a line, nothing read yet
const FIELD_START = 1; // right after a delimiter
const UNQUOTED = 2; // inside a field that does not start with "
const QUOTED = 3; // inside a quoted field
const QUOTE_IN_QUOTED = 4; // just read a " inside a quoted field

class CsvError extends Error {
  constructor(message, line, column) {
    super(`${message} at line ${line}, column ${column}`);
    this.name = 'CsvError';
    this.line = line;
    this.column = column;
  }
}

function normalizeOptions(options) {
  if (options === undefined || options === null) return {};
  if (typeof options !== 'object') throw new TypeError('options must be an object');
  return options;
}

function validateDelimiter(delimiter) {
  if (delimiter === undefined) return ',';
  if (
    typeof delimiter !== 'string' ||
    delimiter.length !== 1 ||
    delimiter === '"' ||
    delimiter === '\r' ||
    delimiter === '\n'
  ) {
    throw new TypeError('delimiter must be a single character other than ", CR or LF');
  }
  return delimiter;
}

function setField(obj, key, value) {
  if (key === '__proto__') {
    Object.defineProperty(obj, key, { value, enumerable: true, writable: true, configurable: true });
  } else {
    obj[key] = value;
  }
}

function createParser(options = {}) {
  options = normalizeOptions(options);
  const delimiter = validateDelimiter(options.delimiter).charCodeAt(0);
  const headerMode = options.header === true;
  const skipEmptyLines = options.skipEmptyLines === true;

  let finished = false;
  let started = false; // whether any input has arrived (for BOM handling)
  let state = RECORD_START;

  // Position tracking. Offsets are absolute UTF-16 offsets into the whole input.
  let base = 0; // offset of the current chunk's first code unit
  let line = 1;
  let lineStart = 0; // offset of the first code unit of the current line
  let crPending = false; // last code unit was a CR line break; a following LF belongs to it

  let field = '';
  let record = [];
  let recordLine = 1;
  let fieldLine = 1;
  let fieldColumn = 1;
  let quoteLine = 1;
  let quoteColumn = 1;

  let header = null; // column names, once the header record is complete
  let headerSeen = headerMode ? new Set() : null;

  let output = [];

  function endField(value) {
    if (headerSeen !== null) {
      if (headerSeen.has(value)) {
        throw new CsvError(`Duplicate header name ${JSON.stringify(value)}`, fieldLine, fieldColumn);
      }
      headerSeen.add(value);
    }
    record.push(value);
    field = '';
  }

  function endRecord() {
    const values = record;
    record = [];
    if (!headerMode) {
      output.push(values);
    } else if (header === null) {
      header = values;
      headerSeen = null;
    } else {
      if (values.length !== header.length) {
        throw new CsvError(
          `Expected ${header.length} field${header.length === 1 ? '' : 's'} but found ${values.length}`,
          recordLine,
          1
        );
      }
      const obj = {};
      for (let k = 0; k < header.length; k++) setField(obj, header[k], values[k]);
      output.push(obj);
    }
  }

  function feed(chunk) {
    const n = chunk.length;
    let i = 0;
    if (!started && n > 0) {
      started = true;
      if (chunk.charCodeAt(0) === BOM) {
        i = 1;
        lineStart = 1;
      }
    }
    let seg = i; // start of the not yet copied part of the current field within this chunk

    for (; i < n; i++) {
      const c = chunk.charCodeAt(i);

      if (crPending) {
        crPending = false;
        if (c === LF) {
          // Second half of a CRLF: no new line. Inside a quoted field it is
          // literal content (still covered by seg); otherwise it is skipped.
          lineStart = base + i + 1;
          continue;
        }
      }

      switch (state) {
        case RECORD_START:
          if (c === CR || c === LF) {
            if (!skipEmptyLines) {
              recordLine = line;
              fieldLine = line;
              fieldColumn = 1;
              endField('');
              endRecord();
            }
            line++;
            lineStart = base + i + 1;
            crPending = c === CR;
            break;
          }
          recordLine = line;
        // falls through
        case FIELD_START:
          fieldLine = line;
          fieldColumn = base + i - lineStart + 1;
          if (c === QUOTE) {
            quoteLine = fieldLine;
            quoteColumn = fieldColumn;
            seg = i + 1;
            state = QUOTED;
          } else if (c === delimiter) {
            endField('');
            state = FIELD_START;
          } else if (c === CR || c === LF) {
            endField('');
            endRecord();
            line++;
            lineStart = base + i + 1;
            crPending = c === CR;
            state = RECORD_START;
          } else {
            seg = i;
            state = UNQUOTED;
          }
          break;

        case UNQUOTED:
          if (c === delimiter) {
            endField(field + chunk.slice(seg, i));
            state = FIELD_START;
          } else if (c === CR || c === LF) {
            endField(field + chunk.slice(seg, i));
            endRecord();
            line++;
            lineStart = base + i + 1;
            crPending = c === CR;
            state = RECORD_START;
          }
          break;

        case QUOTED:
          if (c === QUOTE) {
            field += chunk.slice(seg, i);
            state = QUOTE_IN_QUOTED;
          } else if (c === CR || c === LF) {
            line++;
            lineStart = base + i + 1;
            crPending = c === CR;
          }
          break;

        case QUOTE_IN_QUOTED:
          if (c === QUOTE) {
            // Escaped quote: the second " starts the next literal segment.
            seg = i;
            state = QUOTED;
          } else if (c === delimiter) {
            endField(field);
            state = FIELD_START;
          } else if (c === CR || c === LF) {
            endField(field);
            endRecord();
            line++;
            lineStart = base + i + 1;
            crPending = c === CR;
            state = RECORD_START;
          } else {
            throw new CsvError(
              `Unexpected character ${JSON.stringify(chunk[i])} after closing quote`,
              line,
              base + i - lineStart + 1
            );
          }
          break;
      }
    }

    if (state === UNQUOTED || state === QUOTED) field += chunk.slice(seg, n);
    base += n;
  }

  function finish() {
    if (state === QUOTED) {
      throw new CsvError('Unclosed quoted field', quoteLine, quoteColumn);
    }
    if (state === FIELD_START) {
      // An empty last field after a delimiter starts at the end of input.
      fieldLine = line;
      fieldColumn = base - lineStart + 1;
    }
    if (state !== RECORD_START) {
      endField(field);
      endRecord();
    }
  }

  function guard(fn) {
    if (finished) throw new Error('Parser has already finished');
    try {
      fn();
    } catch (err) {
      finished = true;
      throw err;
    }
    const records = output;
    output = [];
    return records;
  }

  return {
    write(chunk) {
      return guard(() => {
        if (typeof chunk !== 'string') throw new TypeError('chunk must be a string');
        feed(chunk);
      });
    },
    end() {
      return guard(() => {
        finish();
        finished = true;
      });
    },
  };
}

function parse(text, options = {}) {
  if (typeof text !== 'string') throw new TypeError('text must be a string');
  const parser = createParser(options);
  const records = parser.write(text);
  for (const record of parser.end()) records.push(record);
  return records;
}

function formatField(value, delimiter, forceQuote) {
  let text;
  if (typeof value === 'string') text = value;
  else if (typeof value === 'number' || typeof value === 'boolean') text = String(value);
  else if (value === null || value === undefined) text = '';
  else throw new TypeError(`Cannot stringify a value of type ${typeof value}`);

  if (
    forceQuote ||
    text.includes(delimiter) ||
    text.includes('"') ||
    text.includes('\r') ||
    text.includes('\n') ||
    text.startsWith(' ') ||
    text.endsWith(' ')
  ) {
    return '"' + text.replace(/"/g, '""') + '"';
  }
  return text;
}

function formatRecord(values, delimiter, quoteFirst) {
  const parts = new Array(values.length);
  for (let k = 0; k < values.length; k++) {
    parts[k] = formatField(values[k], delimiter, quoteFirst && k === 0);
  }
  // A lone empty field would be an empty line, which parses differently.
  if (parts.length === 1 && parts[0] === '') return '""';
  return parts.join(delimiter);
}

function stringify(rows, options = {}) {
  options = normalizeOptions(options);
  const delimiter = validateDelimiter(options.delimiter);

  let eol = options.eol;
  if (eol === undefined) eol = '\r\n';
  else if (eol !== '\r\n' && eol !== '\n') throw new TypeError("eol must be '\\r\\n' or '\\n'");

  let header = options.header;
  if (header === undefined || header === null || header === false) {
    header = null;
  } else if (!Array.isArray(header) || !header.every((name) => typeof name === 'string')) {
    throw new TypeError('header must be an array of strings');
  }

  if (!Array.isArray(rows)) throw new TypeError('rows must be an array');

  const records = [];
  if (header !== null) records.push(header);
  for (let r = 0; r < rows.length; r++) {
    const row = rows[r];
    if (Array.isArray(row)) {
      records.push(row);
    } else if (header !== null && row !== null && typeof row === 'object') {
      records.push(
        header.map((name) => (Object.prototype.hasOwnProperty.call(row, name) ? row[name] : undefined))
      );
    } else {
      throw new TypeError(header === null ? 'each row must be an array' : 'each row must be an array or an object');
    }
  }
  if (records.length === 0) return '';

  const lines = records.map((values) => formatRecord(values, delimiter, false));
  // A leading U+FEFF would be dropped as a byte order mark when parsed back.
  if (lines[0].charCodeAt(0) === BOM) lines[0] = formatRecord(records[0], delimiter, true);
  return lines.join(eol) + eol;
}

module.exports = { parse, createParser, stringify, CsvError };

