'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { parse, createParser, CsvError } = require('../src/csv');

// Runs the input through a streaming parser split at the given offsets.
function streamParse(text, splits, options) {
  const parser = createParser(options);
  const records = [];
  let prev = 0;
  for (const at of [...splits, text.length]) {
    records.push(...parser.write(text.slice(prev, at)));
    prev = at;
  }
  records.push(...parser.end());
  return records;
}

function outcome(fn) {
  try {
    return { records: fn() };
  } catch (err) {
    assert.ok(err instanceof CsvError, `unexpected ${err && err.stack}`);
    return { error: { line: err.line, column: err.column, message: err.message } };
  }
}

const SAMPLES = [
  '',
  '﻿',
  '﻿a,b\r\nc,d\r\n',
  'a,"b\r\nc",d\re\n\n',
  '"a""b","""",""\r\n\r\n',
  '\r\n\r\r\n\n',
  'x,"y"z',
  'a,b\n"1\r\n2"\n3,"4\r',
  '"never closed\r\n',
  'h1,h2\r\n1,2\r\n3\r\n',
  'h,h\n',
  'h1,h2\n"a""","b"\r\n\n',
