  assert.deepEqual(parse(' a ,b', { trim: true }), [[' a ', 'b']]);
  assert.deepEqual(parse('  \n', { trim: true, skipEmptyLines: true }), [['']]);
});

test('trim does not remove a tab or space delimiter', () => {
  assert.deepEqual(parse(' a\t\tb \n', { trim: true, delimiter: '\t' }), [['a', '', 'b']]);
  assert.deepEqual(parse('a  b\tc', { trim: true, delimiter: ' ' }), [['a', '', 'b', 'c']]);
});

test('trim allows spaces and tabs outside quotes and keeps the quoted content', () => {
  assert.deepEqual(parse(' "  a ""b"" \n" \t,\t"c"  \r\n "d"', { trim: true }), [
    ['  a "b" \n', 'c'],
    ['d'],
  ]);
  assert.deepEqual(parse('  "a"  ', { trim: true }), [['a']]);
  assert.deepEqual(parse('  ""  ,x', { trim: true }), [['', 'x']]);
  assert.deepEqual(parse('a, "b" ', { trim: true, header: true }), []);
});

test('trim: other characters after a closing quote are still errors', () => {
  assertCsvError(() => parse('a, "b" c', { trim: true }), 1, 8, /after closing quote/);
  assertCsvError(() => parse('"b" "', { trim: true }), 1, 5, /after closing quote/);
  assertCsvError(() => parse('  "abc', { trim: true }), 1, 3, /Unclosed/);
  // Without trim, a field with leading spaces is unquoted and quotes are literal.
  assert.deepEqual(parse(' "a" x'), [[' "a" x']]);
});

test('trim applies to header names', () => {
  assert.deepEqual(parse(' a , "b" \n1, 2 ', { trim: true, header: true }), [{ a: '1', b: '2' }]);
  assertCsvError(() => parse('a, a \n', { trim: true, header: true }), 1, 3, /Duplicate/);
});

test('comment lines are skipped with their line break', () => {
  assert.deepEqual(parse('#one\na,b\r\n#two\r\n#three\rc,d\n#end', { comment: '#' }), [
    ['a', 'b'],
    ['c', 'd'],
  ]);
  assert.deepEqual(parse('#x\n\n#y\n', { comment: '#' }), [['']]);
  assert.deepEqual(parse('#x\n\n#y\n', { comment: '#', skipEmptyLines: true }), []);
  assert.deepEqual(parse('#a "quoted\nb', { comment: '#' }), [['b']]);
  assert.deepEqual(parse('﻿#x\na', { comment: '#' }), [['a']]);
  assert.deepEqual(parse('#h\na\n#i\n1', { comment: '#', header: true }), [{ a: '1' }]);
});

test('the comment character is ordinary anywhere but at the start of a line', () => {
  assert.deepEqual(parse('a#,#b\n c,#d', { comment: '#' }), [
    ['a#', '#b'],
    [' c', '#d'],
  ]);
  assert.deepEqual(parse('"a\n#b"\n"#c"', { comment: '#' }), [['a\n#b'], ['#c']]);
  assert.deepEqual(parse(' #a', { comment: '#', trim: true }), [['#a']]);
  assert.deepEqual(parse('#a', { comment: '#', trim: true }), []);
  assert.deepEqual(parse('#a,b\n#c'), [['#a', 'b'], ['#c']]);
});

test('errors count comment lines', () => {
  assertCsvError(() => parse('#a\r\n#b\nx,"y"z', { comment: '#' }), 3, 6, /after closing quote/);
  assertCsvError(() => parse('#a\n\n"b', { comment: '#' }), 3, 1, /Unclosed/);
  assertCsvError(() => parse('#a\nh1,h2\n#b\n1', { comment: '#', header: true }), 4, 1, /Expected 2 fields/);
});

test('invalid comment characters throw TypeError', () => {
  for (const comment of ['', '##', ',', '"', '\r', '\n', 1, null, true, {}]) {
    assert.throws(() => parse('a', { comment }), TypeError, `comment ${JSON.stringify(comment)}`);
  }
  assert.throws(() => parse('a', { comment: ';', delimiter: ';' }), TypeError);
  assert.deepEqual(parse('a', { comment: undefined }), [['a']]);
  assert.deepEqual(parse(';a', { comment: '#', delimiter: ';' }), [['', 'a']]);
});
