const TRIM_COMMENT_SAMPLES = [
  ' a , "b" ,\tc\t\r\n',
  '  "a ""x"" \n" \t,  \n\t \r',
  '#c1\na,b\r\n#c2\r\n\r\n#c3\rc,d\n#',
  'a,#b\n#"never closed\n "x",y#\n',
  '﻿#c\r\n  #not,a comment\r\n#',
  ' "a" x',
  '#a\n"b" ',
  'h1, h1 \n',
  '#a\nh1,h2\n#b\n1\n',
  '  "unclosed',
  '\t\n \n#\n"a"\t"',
];

const TRIM_COMMENT_OPTION_SETS = [
  { trim: true },
  { comment: '#' },
  { trim: true, comment: '#' },
  { trim: true, comment: '#', header: true },
  { trim: true, comment: '#', skipEmptyLines: true },
  { trim: true, comment: ' ', delimiter: ';' },
  { trim: true, comment: '#', delimiter: '\t' },
];

test('trim and comment: every split into three chunks matches parse', () => {
  for (const options of TRIM_COMMENT_OPTION_SETS) {
    for (const text of [...TRIM_COMMENT_SAMPLES, ...SAMPLES]) {
      const expected = outcome(() => parse(text, options));
      for (let a = 0; a <= text.length; a++) {
        for (let b = a; b <= text.length; b++) {
          const actual = outcome(() => streamParse(text, [a, b], options));
          assert.deepEqual(actual, expected, `${JSON.stringify(text)} split at ${a},${b} with ${JSON.stringify(options)}`);
        }
      }
    }
  }
});

test('trim and comment: one code unit per chunk matches parse', () => {
  for (const options of TRIM_COMMENT_OPTION_SETS) {
    for (const text of TRIM_COMMENT_SAMPLES) {
      const splits = Array.from({ length: text.length }, (_, i) => i);
      assert.deepEqual(outcome(() => streamParse(text, splits, options)), outcome(() => parse(text, options)));
    }
  }
});

test('trim and comment streaming', () => {
  const parser = createParser({ trim: true, comment: '#' });
  assert.deepEqual(parser.write('#com'), []);
  assert.deepEqual(parser.write('ment\r'), []);
  assert.deepEqual(parser.write('\n a '), []);
  assert.deepEqual(parser.write('  , "b'), []);
  assert.deepEqual(parser.write('" \t\n#x'), [['a', 'b']]);
  assert.deepEqual(parser.write('\n'), []);
  assert.deepEqual(parser.end(), []);
  assert.throws(() => createParser({ comment: '""' }), TypeError);
  assert.throws(() => createParser({ comment: ',' }), TypeError);
});
